#!/usr/bin/env python3
"""Authored educational facts; external review draft, never a prescription."""
import copy,json,pathlib
HERE=pathlib.Path(__file__).resolve().parent
DATE='2026-11-18';VERSION='0.84.63'
MANIFEST=json.loads((HERE.parent/'sarcoma-batch4-sources-20261118/source-manifest.json').read_text())
SOURCES={s['code']:dict(catalogue_url=s['url'],pages=s['pages'],version=s['version'])for s in MANIFEST['sources']}
ROUTES={c:c for c in SOURCES}
GENERIC='Discuss low blood counts with serious infection or sepsis, anaemia and bleeding; nausea or vomiting; mouth soreness, appetite or taste changes, diarrhoea or constipation; fatigue, hair, nail and skin changes; changes in sexual wellbeing; allergic reactions and intravenous-line complications; blood clots, including clots in the legs or lungs; fertility, pregnancy and breastfeeding effects; and the possibility of lasting organ injury, rare later cancers or death from serious treatment complications. The likelihood and severity differ between medicines and people. Read this general discussion together with every medicine-specific risk.'
FERTILITY='Discuss fertility preservation before treatment. Obtain written contraception, pregnancy and breastfeeding instructions for every medicine, including how long precautions continue after the final dose. Different medicines have different requirements. Contact oncology promptly if pregnancy is possible. Children and young people need age-appropriate information, assent and the applicable parent or guardian consent process.'
ACCESS='The team chooses appropriate intravenous access and explains its care. Report pain, burning, redness or swelling during treatment immediately. If a port or peripherally inserted central catheter is used, confirm dressing, flushing, infection precautions and eventual removal arrangements. Never change pump settings or disconnect an infusion yourself.'
OSTEO='A specialist sarcoma multidisciplinary team plans chemotherapy together with complete removal of the tumour and any other resectable disease sites. The operation, reconstruction, rehabilitation and pathology review are central parts of the plan. Radiotherapy can be considered when surgery is not feasible or margins are inadequate; it is not automatically added to every osteosarcoma course.'
SALVAGE='The specialist sarcoma multidisciplinary team considers prior treatment, sites of disease, whether surgery or radiotherapy could help, clinical trials, symptoms and your priorities. These options have different roles in Ewing sarcoma and osteosarcoma. Rehabilitation and symptom-focused care can accompany anticancer treatment at any stage.'
PRODUCTS={
 'doxorubicin':('Health Products Regulatory Authority: doxorubicin product information','https://assets.hpra.ie/products/Human/27561/Licence_PA2315-083-001_20022024123027.pdf'),
 'cisplatin':('Health Products Regulatory Authority: cisplatin product information','https://assets.hpra.ie/products/Human/22078/Licence_PA0822-199-001_18032025120043.pdf'),
 'methotrexate':('Health Products Regulatory Authority: methotrexate product information','https://assets.hpra.ie/products/Human/22092/Licence_PA0822-206-007_11092026121412.pdf'),
 'ifosfamide':('Health Products Regulatory Authority: ifosfamide product information','https://assets.hpra.ie/products/Human/15731/Licence_PA2299-028-001_11092023124600.pdf'),
 'etoposide':('Health Products Regulatory Authority: etoposide product information, November 2025','https://assets.hpra.ie/products/Human/28093/Licence_PA2059-036-001_14112025143401.pdf'),
 'mifamurtide':('European Medicines Agency: Mepact product information','https://www.ema.europa.eu/en/documents/product-information/mepact-epar-product-information_en.pdf')}

def agent(id,name,kind,mechanism,explanation,watch,risks,visual):
 return dict(id=id,name=name,alias='',type=kind,mechanism=mechanism,explanation=explanation,watch=watch,risks=risks,visual=visual,symptoms=[],source_ids=['nccp',id+'-pi'])
def agents():
 return {
 'doxorubicin':agent('doxorubicin','Doxorubicin','Chemotherapy','Disrupts genetic material and the enzyme that repairs it','Doxorubicin enters deoxyribonucleic acid, the genetic material called DNA, and interferes with topoisomerase II, an enzyme needed when cells copy and repair their genes. This damages tumour cells. Normal marrow, mouth and heart cells can also be injured.','Report fever, mouth ulcers, breathlessness, ankle swelling, palpitations or pain at the drip immediately.',[
 'Low blood counts, serious infection or sepsis, anaemia and bleeding','Nausea, vomiting, mouth ulcers, appetite changes and diarrhoea','Hair loss, fatigue and skin or nail changes','Heart muscle damage or abnormal rhythm; damage can appear later and relates to lifetime anthracycline exposure','Severe local tissue damage if the drug leaks outside the vein; allergic reactions','Fertility and pregnancy harm; uncommon later blood cancers'],['Tumour genetic material is damaged','Cell division is disrupted','Heart and blood-count surveillance']),
 'cisplatin':agent('cisplatin','Cisplatin','Chemotherapy','Crosslinks genetic material','Cisplatin forms links within and between strands of DNA, the genetic material. These links stop cells copying their instructions normally. Kidney cells, the inner ear and nerves may also be injured, so prescribed fluids and organ checks are essential.','Report reduced urine, persistent vomiting, ringing ears, hearing changes, numbness or weakness before further treatment.',[
 'Severe nausea and vomiting; dehydration can worsen kidney injury','Kidney damage and low magnesium, potassium or other electrolytes','Hearing loss or ringing in the ears, sometimes permanent','Numbness, tingling or weakness from nerve damage, sometimes lasting','Low blood counts, serious infection, anaemia and bleeding','Allergic reactions, infusion-site injury, fertility and pregnancy harm'],['Genetic strands become crosslinked','Tumour replication is interrupted','Kidney, hearing and nerve checks']),
 'methotrexate':agent('methotrexate','High-dose methotrexate','Chemotherapy','Blocks folate-dependent production of genetic material','Methotrexate blocks processes that use folate to make DNA, the genetic material. At this high dose it requires carefully timed folinic acid rescue to protect healthy cells. The kidneys remove methotrexate: slow removal can increase exposure and severe toxicity. Hydration, urine alkalinisation, blood levels and rescue are inseparable parts of treatment.','Report mouth ulcers, severe diarrhoea, reduced urine, dry cough, breathlessness or new neurological symptoms urgently. Do not stop rescue medicine or start other medicines yourself.',[
 'Low blood counts, serious infection or sepsis, anaemia and bleeding','Severe mouth or bowel inflammation and ulceration, nausea, vomiting and diarrhoea','Kidney injury and delayed clearance; toxicity may require prolonged admission and intensified rescue','Liver injury and liver-test changes; lung inflammation','Uncommon serious brain or nerve effects and severe skin reactions','Fertility and pregnancy harm, rare later cancers and serious interactions with other medicines'],['Folate-dependent synthesis is blocked','Tumour and normal cells are affected','Timed folinic acid protects healthy cells']),
 'ifosfamide':agent('ifosfamide','Ifosfamide','Chemotherapy','A liver-activated medicine damages genetic material','The liver converts ifosfamide into active compounds that crosslink DNA, the genetic material, preventing normal cell division. Other breakdown products can damage the bladder, kidneys or brain. Mesna reduces bladder injury; it does not prevent kidney injury or brain toxicity.','New confusion, unusual sleepiness, hallucinations, unsteadiness, seizures, blood in urine or reduced urine needs immediate assessment.',[
 'Low blood counts, serious infection or sepsis, anaemia and bleeding','Nausea, vomiting, mouth soreness, hair loss and fatigue','Brain toxicity, called encephalopathy: confusion, drowsiness, hallucinations or seizures; may be severe','Kidney tubular injury, electrolyte loss and reduced kidney function, which may persist','Bladder inflammation and bleeding despite protective mesna; report blood or pain when passing urine','Possible heart or lung injury, allergic reactions, fertility and pregnancy harm, and later cancers'],['Liver activates the medicine','DNA crosslinks damage tumour cells','Mesna protects the bladder only']),
 'etoposide':agent('etoposide','Etoposide','Chemotherapy','Prevents repair of breaks in genetic material','Etoposide interferes with topoisomerase II, an enzyme that controls breaks in DNA, the genetic material. Damaged tumour cells cannot divide normally. The bone marrow and other healthy tissues are also affected.','Tell the nurse immediately about dizziness, flushing, rash, chest tightness, breathlessness or feeling faint during infusion.',[
 'Low blood counts, serious infection or sepsis, anaemia and bleeding','Nausea, vomiting, appetite loss, mouth soreness, diarrhoea or constipation','Hair loss and fatigue','Allergic or severe infusion reactions and low blood pressure, especially if given too quickly','Local inflammation or tissue damage around the infusion site; liver effects and rare severe skin reactions','Fertility and pregnancy harm and uncommon later blood cancers'],['DNA repair is interrupted','Dividing cells are damaged','Slow infusion and blood-count checks']),
 'mifamurtide':agent('mifamurtide','Mifamurtide','Innate immune activator','Activates monocytes and macrophages','Mifamurtide resembles part of a bacterial cell wall and stimulates monocytes and macrophages, cells of the innate immune system. The aim is to help these cells act against remaining osteosarcoma cells after complete surgery. It accompanies postoperative chemotherapy. It is not an immune checkpoint inhibitor.','Report fever or sudden illness immediately, even when fever has happened after an earlier infusion. New wheeze, breathing difficulty, chest pain or faintness needs urgent assessment.',[
 'Fever, chills, headache, fatigue, muscle or joint aches and sweating','Nausea, vomiting, diarrhoea, constipation and appetite loss; dehydration can occur','Breathlessness or wheeze, particularly with asthma; severe respiratory or allergic reactions','Rapid heartbeat, blood-pressure changes, palpitations or chest pain','Uncommon pronounced inflammatory reactions, including inflammation around the heart or lungs; caution with inflammatory or autoimmune disease','Dizziness, blurred vision and effects on driving; blood-count abnormalities or infection can occur alongside chemotherapy; pregnancy safety and fertility data are limited'],['Innate immune cells are activated','Treatment follows complete surgery','Chemotherapy continues on its own schedule'])}

def test(label,purpose,timing,kind='blood',scope='routine',sources=None):
 return dict(label=label,purpose=purpose,timing=timing,kind=kind,scope=scope,source_ids=sources or ['nccp'])
def anatomy(code,names):
 coords={'brain':(50,7),'hearing':(68,13),'mouth':(43,16),'heart':(46,25),'lungs':(64,26),'liver':(43,33),'kidneys':(39,40),'bladder':(50,49),'blood':(64,55),'bowel':(57,39),'skin':(65,70),'nerves':(35,77),'joints':(34,64)}
 text={
 'brain':('Brain and alertness','New confusion, unusual sleepiness, hallucinations, unsteadiness or seizures needs immediate assessment.'),
 'hearing':('Hearing','Report ringing ears or reduced hearing promptly. Hearing changes can persist.'),
 'mouth':('Mouth','Report ulcers, painful swallowing or difficulty eating and drinking early.'),
 'heart':('Heart','New breathlessness, chest pain, palpitations, faintness or swelling needs urgent assessment.'),
 'lungs':('Breathing','Report new wheeze, cough or breathlessness promptly; severe breathing difficulty is an emergency.'),
 'liver':('Liver','Blood tests monitor liver effects; report yellow eyes or dark urine promptly.'),
 'kidneys':('Kidneys','Report reduced urine or inability to drink. Kidney damage and electrolyte losses may need extra tests.'),
 'bladder':('Bladder','Report blood or pain when passing urine immediately. Mesna reduces bladder injury but does not remove all risk.'),
 'blood':('Blood cells and infection','Fever, shaking chills, sudden illness or unusual bleeding requires immediate oncology advice.'),
 'bowel':('Bowel and appetite','Use prescribed anti-sickness support; report persistent vomiting, severe diarrhoea or difficulty drinking.'),
 'skin':('Skin, hair and infusion line','Hair and skin changes may occur. Report line-site pain, burning, swelling or a severe rash immediately.'),
 'nerves':('Nerves and function','Report tingling, numbness or weakness before another dose; these effects can affect walking or hand tasks.'),
 'joints':('Muscles and joints','Aches may occur. New swollen joints or persistent worsening inflammatory symptoms need review.')}
 keys={'00420':['hearing','mouth','heart','kidneys','blood','bowel','skin','nerves'],'00463':['brain','hearing','mouth','heart','liver','kidneys','blood','bowel'],'00100':['brain','heart','lungs','liver','kidneys','blood','bowel','joints'],'00596':['brain','mouth','heart','kidneys','bladder','blood','bowel','skin'],'00680':['brain','mouth','heart','kidneys','bladder','blood','bowel','skin']}[code]
 if code=='00100':
  text['brain']=('Headache and dizziness','Headache or dizziness may follow infusion. Severe headache, confusion, seizures or collapse needs urgent assessment.')
  text['blood']=('Fever and infection','Fever may follow infusion but can also signal serious infection. Do not wait eight hours before seeking advice if unwell.')
  text['kidneys']=('Kidney monitoring','Blood and urine checks monitor kidney function during combined treatment and after chemotherapy finishes until the whole course ends. Report blood or pain when passing urine, reduced urine or difficulty drinking promptly.')
  text['liver']=('Liver monitoring','Liver blood tests continue during combined treatment and after chemotherapy ends until all therapy is complete. Report yellow eyes, dark urine or new significant abdominal pain promptly.')
 return [[k,text[k][0],'Combined mifamurtide and chemotherapy monitoring'if code=='00100'and k in ['kidneys','liver']else names,text[k][1],*coords[k]]for k in keys]

def facts():
 a=agents();f={}
 f['00420']=dict(title='Doxorubicin and cisplatin for osteosarcoma',context='Chemotherapy before and after surgery for osteosarcoma',purpose='Chemotherapy treats osteosarcoma cells throughout the body, including cells too small to see on scans, alongside surgery intended to remove the visible cancer.',days=21,kind='cycle',label='Doxorubicin days 1–3 and cisplatin day 1; six 21-day cycles',agents=[a['doxorubicin'],a['cisplatin']],schedule='Doxorubicin 25 mg/m² is given on days 1, 2 and 3; cisplatin 100 mg/m² on day 1. The reference course contains six 21-day cycles, usually three before surgery and three afterwards, with pathology review. Treatment dates and doses depend on recovery and the specialist plan.',administration='Doxorubicin is given through supervised intravenous access. Cisplatin is infused over 2 hours, with prescribed fluids and electrolytes before and afterwards. The full visit is longer than the drug infusion. A hospital fluid prescription is not a home drinking target.',baseline='Blood counts, kidney and liver tests, heart tracing and review of previous anthracycline exposure. Heart imaging, hearing tests and measured kidney clearance are arranged when clinically indicated.',monitoring='Blood counts and kidney/liver tests before each cycle. Review hearing, nerve symptoms, fluid balance and cardiac symptoms; additional organ tests are risk- or symptom-directed.',prep='Bring the full medicine list, report infection or hearing/nerve changes, and confirm the anti-sickness and hydration prescription. Discuss heart history, all prior anthracyclines, fertility and the surgery plan.',support='Cisplatin has high nausea/vomiting risk. Agree prevention and rescue anti-sickness medicines, prescribed hydration and electrolyte replacement. A separate white-cell growth-factor plan may be chosen for clinical need. Do not add diuretics or change fluid intake yourself.',access=ACCESS,wider=OSTEO,scope='This is the six-cycle doxorubicin/cisplatin course. It is distinct from the surgery-linked high-dose methotrexate combination. The national source gives no numeric age cutoff. Lifetime anthracycline exposure and individual heart risk must be reconciled.',trial='European Osteosarcoma Intergroup historical randomised comparison',trial_url='https://pubmed.ncbi.nlm.nih.gov/9314869/',evidence='A historical randomised study of operable, nonmetastatic osteosarcoma found similar observed five-year survival and progression outcomes with six courses of doxorubicin/cisplatin and a much longer multidrug course. More patients completed the shorter course.',caveat='The comparator was a historical 44-week regimen. This is not a modern direct comparison against methotrexate/doxorubicin/cisplatin and does not prove equivalence to all current regimens or predict an individual outcome.',doses=[('doxo','Doxorubicin',1,3,'25 mg/m² each day on days 1–3.'),('cis','Cisplatin',1,1,'100 mg/m² on day 1 over 2 hours, with prescribed hydration.')],phases=[('d1','Day 1: doxorubicin and cisplatin',['Doxorubicin','Cisplatin'],'high'),('d2d3','Days 2–3: doxorubicin',['Doxorubicin'],'moderate')],course='Six planned 21-day cycles, usually three before and three after surgery',urgent='Report new hearing loss, reduced urine, persistent vomiting, chest symptoms or painful infusion sites urgently.',boundaries=['NCCP has no numeric age limit; performance status 0–2 and adequate organ function are stated.','Six full cycles give a planned doxorubicin total of 450 mg/m²; the source also states a 450 mg/m² lifetime ceiling. Prior anthracyclines and cardiac risk may lower the allowable individual exposure.','The source heart thresholds leave exact 50% pumping function ambiguous. Decimal gaps in kidney/liver dose bands require specialist interpretation, not a patient calculator.'],tests=[test('Full blood count','Check infection-fighting cells, haemoglobin and platelets.','Before starting and before each 21-day cycle; repeat sooner for fever, bleeding or abnormal results.'),test('Kidney function and electrolytes','Assess cisplatin kidney safety and identify magnesium or other electrolyte losses.','Before starting and before each cycle; additional checks accompany the prescribed hydration plan and reduced urine, dehydration or abnormal results.'),test('Liver tests','Assess doxorubicin handling and detect liver injury.','Before starting and before each cycle; repeat when results or symptoms warrant.'),test('Heart tracing and heart imaging','Assess cardiac risk alongside lifetime anthracycline exposure.','Heart tracing before starting. Heart ultrasound or multigated acquisition scan if age above 65 or clinically indicated in the source; repeat imaging when indicated by symptoms or risk.','procedure','conditional'),test('Hearing assessment','Identify cisplatin-related hearing injury.','Review symptoms before further cisplatin; formal audiology at baseline or later when clinically indicated. Report changes immediately.','procedure','conditional'),test('Nerve and symptom review','Detect neuropathy and other treatment effects before more dosing.','At each treatment review and whenever numbness, weakness or other symptoms change.','review'),test('Surgery, pathology and response review','Coordinate cancer control and postoperative treatment.','Review at the planned transition after three preoperative cycles and after surgery; scans and further reviews follow the consultant-set plan.','scan','conditional')])
 f['00463']=dict(title='Methotrexate, doxorubicin and cisplatin for osteosarcoma',context='High-grade osteosarcoma of an extremity or axial skeleton, excluding craniofacial sites, with all disease sites amenable to complete surgical resection; national eligibility age 40 years or younger',purpose='The three medicines act through different mechanisms against osteosarcoma throughout the body. Surgery removes the visible tumour, and chemotherapy before and after surgery aims to reduce recurrence risk.',days=203,kind='reference-course',label='Surgery-linked reference course: weeks 1–10, surgery week 11, then weeks 12–29',agents=[a['methotrexate'],a['doxorubicin'],a['cisplatin']],schedule='The reference plan is not a repeating 21-day cycle. Before surgery, doxorubicin 37.5 mg/m² and cisplatin 60 mg/m² are each given on days 1 and 2 of weeks 1 and 6; methotrexate 12 g/m² is given on day 1 of weeks 4, 5, 9 and 10. Surgery is planned for reference week 11. Afterwards, doxorubicin is given on days 1 and 2 of weeks 12, 17, 22 and 26; cisplatin on days 1 and 2 of weeks 12 and 17; methotrexate on day 1 of weeks 15, 16, 20, 21, 24, 25, 28 and 29. Actual dates depend on surgery, recovery, drug clearance and safety review.',administration='Methotrexate is infused over 4 hours after at least 6 hours of prescribed hydration and urine alkalinisation. Folinic acid rescue starts 24 hours after the methotrexate infusion starts, usually every 6 hours initially, and is adjusted to timed levels and kidney function. Cisplatin runs over 4 hours with its own fluid prescription. Doxorubicin may be given by intravenous push or a separately prescribed 48-hour central-line infusion.',baseline='Blood counts, kidney/liver tests, coagulation tests, urine dipstick and heart tracing; heart and hearing assessment when indicated. Confirm kidney safety, interacting medicines and any abnormal fluid collections before high-dose methotrexate.',monitoring='Blood counts and kidney/liver tests before each treatment. Methotrexate requires daily creatinine, timed drug levels, six-hourly urine acidity checks and four-hourly fluid balance, plus further tests when clearance is delayed. Review hearing and nerve effects before each course.',prep='Confirm the entire methotrexate admission, rescue, blood-level and interaction plan. Ask oncology/pharmacy before any new prescription, over-the-counter painkiller, antibiotic or supplement. Agree the operation and recovery plan, fertility preservation and line arrangements.',support='Cisplatin has high nausea/vomiting risk; doxorubicin and high-dose methotrexate have moderate risk. Each visit needs its own reconciled anti-sickness prescription. Methotrexate hydration, alkalinisation, level monitoring and folinic acid rescue must continue until the specialist team confirms safe clearance. Delayed clearance may need intensified rescue or glucarpidase. No fixed discharge day is promised.',access=ACCESS,wider=OSTEO,scope='This course is limited to the stated age, site and complete-resection context. Up to two additional preoperative methotrexate doses may be prescribed if surgery is delayed. These are not automatic. Poor response on surgical pathology does not automatically justify adding ifosfamide/etoposide.',trial='EURAMOS-1: preoperative platform and randomised MAPIE versus MAP in poor responders',trial_url='https://pubmed.ncbi.nlm.nih.gov/27569442/',evidence='The international study established a large practical treatment platform. In the separate randomised comparison after a poor pathological response, adding ifosfamide and etoposide did not improve event-free survival and increased toxicity. The specialist team interprets pathology together with the whole treatment plan.',caveat='The pre-randomisation report is not comparative survival proof. The poor-response randomisation studied postoperative intensification, not treatment of relapse. Its result must not be used to withhold all future salvage options.',doses=[],phases=[('doxocis','Doxorubicin/cisplatin treatment weeks',['Doxorubicin','Cisplatin'],'high'),('doxo','Postoperative doxorubicin-only treatment weeks',['Doxorubicin'],'moderate'),('mtx','High-dose methotrexate weeks and rescue',['Methotrexate'],'moderate')],course='Reference course through week 29, with surgery and clearance-dependent timing',urgent='Reduced urine, severe mouth ulcers or diarrhoea, new neurological symptoms or delayed methotrexate clearance needs urgent specialist assessment.',boundaries=['Age ≤40; source anatomical exclusions and complete resectability of all sites apply. No generic 21-day repeating calendar.','Source kidney wording conflicts: creatinine clearance ≥50 mL/min eligibility, an indexed 70 mL/min/1.73 m² warning and a renal-toxicity row with a problematic ≥50 sign. Indexed and unindexed units are not interchangeable. Specialist review is required.','Source methotrexate hydration and rescue stopping thresholds differ (0.1 versus 0.15 micromol/L), a printed molar exponent is inconsistent, and the postoperative 11-dose/84-hour alternative must not stop rescue during delayed clearance. No automated rescue/discharge rule is provided.','All rescue clocks start at methotrexate infusion commencement, not completion. Rescue-table interval overlaps and the alternative formula require specialist/pharmacy adjudication.','Planned standard-course arithmetic: doxorubicin 450 mg/m², cisplatin 480 mg/m² and twelve methotrexate administrations; optional delay doses are separate. Prior anthracycline exposure and cardiac risk remain relevant.','Dose-modification source gaps, exact cardiac boundary and historical toxicity must be reviewed. No numerical dose modification or rescue calculator is authorised.'],tests=[test('Full blood count','Check infection, anaemia and bleeding risk for the selected drug phase.','Before starting and before each treatment, with repeat checks as indicated. Methotrexate and doxorubicin/cisplatin use different source treatment thresholds.'),test('Kidney function and daily creatinine','Assess high-dose methotrexate clearance and cisplatin injury.','Before each treatment; creatinine daily during methotrexate administration and clearance monitoring. Further testing follows a rise in creatinine or delayed clearance.'),test('Methotrexate blood concentration','Guide safe continuation and adjustment of folinic acid rescue.','At 24, 48, 72, 96 and 120 hours as appropriate from the actual infusion START; continue later measurements if the specialist clearance plan requires them.'),test('Urine acidity','Reduce methotrexate precipitation in the kidneys.','Confirm urine pH at least 7 before methotrexate, then check every 6 hours during methotrexate and rescue while prescribed alkalinisation continues.','urine'),test('Fluid balance and hydration','Maintain clearance while identifying fluid retention or reduced output.','Begin prescribed prehydration at least 6 hours before methotrexate; record fluid balance every 4 hours during treatment. Cisplatin has a separate pre/post-hydration prescription.','review'),test('Liver tests','Detect hepatic effects and interpret persistent abnormalities.','Before each treatment; repeat after abnormal results or symptoms. The team distinguishes expected transient methotrexate-related changes from persistent injury.'),test('Coagulation and urine screening','Identify baseline bleeding and urinary abnormalities.','Coagulation tests and urine dipstick for blood, protein and glucose before starting; repeats are directed by findings and the clinical plan.','blood'),test('Heart function','Detect anthracycline injury.','Heart tracing before starting; imaging when clinically indicated. Symptoms or abnormal pumping measurements trigger a specific reassessment before further doxorubicin.','procedure','conditional'),test('Hearing and nerve assessment','Identify cisplatin injury that may change future doses.','Assess hearing symptoms and sensory nerve damage before each course; audiology when clinically indicated.','procedure','conditional'),test('Surgery, pathology and tumour review','Connect local treatment, response and postoperative planning.','Plan surgery at reference week 11 after induction, review resection/pathology afterwards, and individualise imaging and follow-up.','scan','conditional')])
 f['00100']=dict(title='Mifamurtide after osteosarcoma surgery',context='High-grade, resectable, nonmetastatic osteosarcoma after macroscopically complete resection, alongside postoperative multi-agent chemotherapy; national age eligibility 2–30 years',purpose='Mifamurtide stimulates innate immune cells to help act against remaining osteosarcoma cells after complete surgery. It is an additional postoperative treatment discussed with the patient and family, alongside chemotherapy.',days=252,kind='reference-course',label='48 infusions over 36 weeks: twice weekly for 12 weeks, then weekly for 24 weeks',agents=[a['mifamurtide']],service_kind='systemic anticancer therapy',schedule='Mifamurtide 2 mg/m² is infused over 1 hour after complete resection and surgical recovery. Give two infusions each week for the first 12 weeks, at least 3 days apart, then one infusion weekly for another 24 weeks: 48 infusions over 36 weeks. This timetable runs separately from the chemotherapy calendar. The specialist team confirms the actual postoperative start and any delays.',administration='A specialist team prepares and gives a one-hour intravenous infusion; it must not be given as a rapid bolus. Mifamurtide and doxorubicin or other fat-soluble medicines should have separate administration times. Treatment preparation uses the supplied filter; that is distinct from an administration-line filter.',baseline='Blood counts, kidney/liver function and review of asthma, inflammatory disease, clotting or cardiovascular history, allergies, all medicines and postoperative recovery.',monitoring='Blood counts and kidney/liver function before source-defined treatment cycles, with the team writing the actual visit plan. Kidney and liver surveillance continues after chemotherapy finishes until all mifamurtide treatment ends. Observe for infusion, respiratory, inflammatory and cardiovascular reactions.',prep='Confirm that complete surgery and nonmetastatic eligibility are met. Review calcineurin inhibitors, anti-inflammatory painkillers and steroids. Any premedication must be individually prescribed, especially for a child. Arrange the separate 36-week treatment record.',support='Mifamurtide has moderate nausea/vomiting risk. Agree an individual anti-sickness plan without automatically adding routine dexamethasone or chronic steroids, which may oppose immune-cell activation. Paracetamol or an antihistamine may be prescribed for infusion symptoms; adult examples are not paediatric doses. Preventive inhaler treatment may be considered for asthma or chronic obstructive lung disease.',access=ACCESS,wider=OSTEO+' Mifamurtide is an adjunct to postoperative multi-agent chemotherapy, not a replacement for it.',scope='Only the completely resected, nonmetastatic postoperative context is covered. European product information describes evidence in patients aged 2–30 at initial diagnosis; the team reconciles this with the national age wording. Mifamurtide is an innate immune activator, not a checkpoint inhibitor, and should not automatically receive checkpoint-specific consent or steroid pathways.',trial='Randomised factorial trial of mifamurtide in resectable nonmetastatic osteosarcoma',trial_url='https://pubmed.ncbi.nlm.nih.gov/18235123/',evidence='A randomised study of 662 patients reported improved overall survival when mifamurtide was added to surgery and chemotherapy. The event-free survival difference was less certain. The team should discuss the potential benefit, the treatment burden of 48 infusions and uncertainty for the individual.',caveat='The population had resectable nonmetastatic disease. The result cannot be assumed in relapsed or metastatic disease. Earlier and later analyses differed in their treatment-interaction findings; an observed group difference is not a guaranteed benefit for one person.',doses=[],phases=[('twiceweekly','First 12 weeks: two infusions at least 3 days apart',['Mifamurtide'],'moderate'),('weekly','Next 24 weeks: one infusion weekly',['Mifamurtide'],'moderate')],course='48 planned infusions over 36 weeks after surgery and recovery',urgent='Do not wait eight hours to seek advice for fever or sudden illness. Severe wheeze, breathing difficulty, chest pain or faintness needs urgent assessment.',boundaries=['Complete macroscopic resection, nonmetastatic presentation and postoperative multi-agent chemotherapy are required context. No unsupported performance-status limit is added.','The 36-week clock is independent of chemotherapy: 24 infusions over the first 12 weeks and 24 over the next 24 weeks. Initial twice-weekly infusions are at least three days apart.','Avoid concurrent calcineurin inhibitors and high-dose nonsteroidal anti-inflammatory drugs. Avoid routine/chronic corticosteroids; emergency treatment is a separate clinical decision.','Severe respiratory reactions require discontinuing administration and treating the reaction. Neutropenia alone does not automatically import a cytotoxic count hold, but fever needs prompt review.','The national regular-test wording is before each cycle; the team must define a written calendar for this non-cyclic schedule rather than inventing a universal every-infusion frequency.'],tests=[test('Full blood count','Identify anaemia, low infection-fighting cells and bleeding risk during combined treatment.','Before starting and before each treatment cycle under the national wording; the specialist team records the actual calendar during the twice-weekly and weekly phases. Additional testing follows fever, bleeding or abnormal results.'),test('Kidney function','Track kidney safety during and beyond concurrent chemotherapy.','Before starting and at the scheduled treatment-cycle reviews; continue monitoring after chemotherapy ends until mifamurtide therapy is complete, as directed by the treating team.',sources=['nccp','mifamurtide-pi']),test('Liver tests','Track liver function while the complete course continues.','Before starting and at treatment-cycle reviews; continue after chemotherapy ends until all mifamurtide is complete. Increase surveillance for moderate impairment or new abnormalities.',sources=['nccp','mifamurtide-pi']),test('Clotting tests','Identify changes in clotting parameters.','European product information recommends testing after the first dose and again after several doses; the team specifies those appointments.',sources=['mifamurtide-pi']),test('Heart assessment','Review cardiac history and ongoing therapy effects.','National source specifies echocardiography annually or according to local practice. Concurrent anthracycline treatment may require additional heart checks on its own schedule.','procedure','conditional'),test('Breathing, allergy, inflammation and vital signs','Detect respiratory, cardiovascular or exaggerated inflammatory reactions.','Review relevant history before starting; observe during administration and assess new or worsening symptoms immediately between visits.','review',sources=['nccp','mifamurtide-pi']),test('Postoperative and disease review','Confirm recovery and follow the wider osteosarcoma plan.','Confirm complete resection and operative recovery before the first dose; disease assessments follow the consultant-set schedule throughout and after treatment.','scan','conditional')])
 common_ifos_tests=[test('Full blood count','Assess infection risk, anaemia and bleeding risk.','Before starting and before each 21-day cycle; extra testing follows fever, bleeding or abnormal results.'),test('Kidney and liver tests','Assess drug handling and detect organ injury.','Before starting and before each cycle. Kidney filtration and tubular function also need assessment during and after ifosfamide, with timing intensified for abnormal results or symptoms.'),test('Neurological assessment','Detect early ifosfamide brain toxicity.','Before EVERY ifosfamide dose and urgently for new confusion, sleepiness, hallucinations, unsteadiness or seizures.','review'),test('Urine checks for blood','Detect bladder injury despite mesna.','Before each ifosfamide dose and every 8 hours on treatment days; report blood or urinary pain immediately.','urine'),test('Fluid balance and weight','Detect low urine output, fluid retention and dehydration.','Monitor fluid balance during treatment and record weight daily. Prescribed hydration begins before ifosfamide and continues for 24 hours after the final ifosfamide infusion ends.','review'),test('Tumour, symptom and function review','Assess benefit separately from treatment safety.','Before continuation at the specialist-set review points; scan timing depends on the individual Ewing sarcoma or osteosarcoma treatment plan.','scan','conditional')]
 f['00596']=dict(title='Ifosfamide and etoposide for Ewing sarcoma or osteosarcoma',context='Relapsed Ewing sarcoma, or treatment of osteosarcoma under the national source indication',purpose='The two medicines damage tumour genetic material through different mechanisms to help control sarcoma. The intended role, chance of benefit and how this fits with surgery, radiotherapy or trials depend on the diagnosis and previous treatment.',days=21,kind='cycle',label='Etoposide then ifosfamide on days 1–5; repeat every 21 days, up to 7 cycles',agents=[a['ifosfamide'],a['etoposide']],schedule='Etoposide 100 mg/m² is infused over 60 minutes, followed by ifosfamide 1,800 mg/m² over 60 minutes, on each of days 1–5. Courses repeat every 21 days for up to seven cycles while benefit and tolerability justify treatment. Mesna is given before each ifosfamide infusion and at 4 and 8 hours measured from its START.',administration='The daily sequence includes etoposide, protective mesna, then ifosfamide, with further mesna at the prescribed times. Hydration starts before the first ifosfamide dose and continues for 24 hours after the last dose ends. Monitoring and supportive treatment make attendance longer than the drug infusion times.',baseline='Blood counts, kidney/liver profiles, sodium, potassium and phosphate, plus neurological and urinary assessment and review of prior treatment and medicines.',monitoring='Blood counts and kidney/liver profiles before each cycle; sodium, potassium and phosphate are included in the regular source tests. Check neurological function before every ifosfamide dose and urine for blood before every dose and every 8 hours during treatment.',prep='Confirm mesna, hydration, white-cell growth-factor support and the complete five-day anti-sickness plan. Review interactions including aprepitant with ifosfamide. The source identifies this etoposide indication as unlicensed in Ireland: the patient must be informed and consented under hospital policy, with acknowledgement by the local Drugs and Therapeutics Committee or equivalent.',support='This combination has high overall nausea/vomiting risk and requires white-cell growth-factor support for every cycle, timed by local prescription. Mesna reduces bladder injury but does not protect the kidneys or brain. Pharmacy must review anti-sickness interactions, particularly aprepitant, and specify all delayed and rescue treatment.',access=ACCESS,wider=SALVAGE,scope='Relapse is explicit for Ewing sarcoma; the national osteosarcoma indication does not add a relapse qualifier. The source gives no numeric age cutoff. Etoposide use for this indication is unlicensed in Ireland and requires the documented local discussion and governance process.',trial='Historical phase II ifosfamide/etoposide study in recurrent tumours of children and young adults',trial_url='https://pubmed.ncbi.nlm.nih.gov/3114435/',evidence='A historical single-arm study showed tumour shrinkage in some previously treated patients, including small groups with Ewing sarcoma and osteosarcoma. The lack of a comparison group and very small disease-specific groups limit the estimate of benefit for today’s individual patient.',caveat='Of 124 enrolled patients, 77 were evaluable for response. Mixed tumour types, small subgroups and short follow-up limit interpretation. The trial’s longer course must not replace the current national maximum of seven cycles. Response does not establish improved survival.',doses=[('etop','Etoposide',1,5,'100 mg/m² over 60 minutes each day, before ifosfamide.'),('ifos','Ifosfamide',1,5,'1,800 mg/m² over 60 minutes each day, after protective mesna.'),('mesna','Mesna protection',1,5,'360 mg/m² before each ifosfamide dose, then at 4 and 8 hours from ifosfamide START; administration is prescribed by the team.'),('hydration','Continued hydration',1,6,'Starts before ifosfamide and continues 24 hours after the final infusion ends; exact finish depends on actual times.')],phases=[('days1to5','Five-day etoposide/ifosfamide course and post-treatment support',['Etoposide','Ifosfamide'],'high')],course='Up to seven 21-day cycles, stopping earlier for progression or unacceptable toxicity',urgent='Any new confusion or unusual sleepiness, blood in urine, low urine output or infusion-related faintness needs immediate assessment.',boundaries=['The etoposide indication is explicitly unlicensed in Ireland: explain and consent under hospital policy and confirm local Drugs and Therapeutics Committee acknowledgement.','National renal etoposide bands differ from current product wording; below-normal kidney function or dialysis requires individual pharmacy/consultant reconciliation. The extracted AST table omits units; do not infer them.','Neurological management depends on current symptoms, severity, previous occurrences and documented recovery. Re-exposure, methylene blue or substitution requires a new specialist decision; none is automatically prescribed.','Ifosfamide kidney clearance below 50 mL/min or dialysis is a clinical decision, not an imported absolute rule from another regimen. Severe liver impairment is not recommended.'],tests=copy.deepcopy(common_ifos_tests)+[test('Sodium, potassium and phosphate','Detect electrolyte losses including ifosfamide tubular injury.','At baseline and as regular tests with treatment-cycle reviews; repeat during treatment or recovery when results, fluid balance or symptoms require.'),test('Blood pressure and etoposide reaction monitoring','Detect infusion-related hypotension or allergy.','Monitor during infusion, especially the first 15 minutes. Tell staff immediately about dizziness, flushing, breathlessness or feeling faint.','review')])
 f['00680']=dict(title='High-dose ifosfamide for recurrent Ewing sarcoma or relapsed osteosarcoma',context='Recurrent or primary refractory Ewing sarcoma, or relapsed osteosarcoma',purpose='High-dose ifosfamide aims to control previously treated sarcoma and can sometimes make further local treatment possible. The specialist team weighs potential tumour shrinkage against substantial bone-marrow, brain, kidney and bladder risks.',days=21,kind='cycle',label='Five consecutive 24-hour ifosfamide infusions; every 21 days, maximum 4 cycles',agents=[a['ifosfamide']],schedule='Ifosfamide 3,000 mg/m² is infused over 24 hours on each of days 1–5, giving five consecutive 24-hour infusions. Repeat every 21 days for a maximum of four cycles unless progression or unacceptable toxicity stops treatment sooner. Mesna starts before the first infusion, continues throughout the five-day treatment and includes a final dose on day 6 after the last ifosfamide infusion.',administration='The five 24-hour ifosfamide infusions total 120 hours at the full reference schedule. Mesna 400 mg/m² is given one hour before the first ifosfamide dose, then 3,000 mg/m² over each 24 hours alongside ifosfamide, with a final 800 mg/m² intravenous dose on day 6 after completion. Hydration continues for 24 hours after ifosfamide ends. Actual bag changes, finish times and any alternative final mesna route require pharmacy confirmation.',baseline='Blood counts and kidney/liver profiles, with neurological, urinary and fluid-status assessment and review of prior chemotherapy and medicines.',monitoring='Blood counts and kidney/liver tests before each cycle. Assess neurological function before every ifosfamide dose and urine for blood before each dose and every 8 hours on treatment days. Monitor fluid balance and daily weight, and kidney filtration and tubular function during and after treatment.',prep='Confirm the five-day infusion admission, mesna, hydration, daily bag changes, white-cell growth-factor support and anti-sickness prescription. Review previous ifosfamide neurological problems and interacting medicines, including aprepitant.',support='This high-dose regimen has high nausea/vomiting risk and requires white-cell growth-factor support. Mesna and prescribed hydration are essential but do not remove kidney or brain toxicity. The anti-sickness plan needs specific interaction review and coverage for treatment and delayed symptoms.',access=ACCESS,wider=SALVAGE,scope='The maximum is four cycles. The detailed national eligibility paragraph describes Ewing sarcoma; its timing definitions must not be copied automatically into the separately listed relapsed osteosarcoma indication. No numeric age or performance-status cutoff is invented.',trial='High-dose ifosfamide cohorts in Ewing sarcoma and relapsed osteosarcoma',trial_url='https://pubmed.ncbi.nlm.nih.gov/19142994/',evidence='Small Ewing sarcoma and retrospective osteosarcoma studies reported tumour shrinkage in some patients. Severe blood-count toxicity was frequent in the Ewing study. These studies support a carefully selected disease-control discussion but cannot establish a comparative survival benefit.',caveat='Ewing and osteosarcoma results come from different uncontrolled populations and must not be combined or used to rank regimens. Surgery and patient selection affect the osteosarcoma survival figures. The current national course maximum remains four cycles.',doses=[('ifos','Ifosfamide: five 24-hour infusions',1,6,'Starts day 1 and runs for 120 hours across days 1–5 into day 6; this is not six full doses.'),('mesna','Mesna before and during infusion',1,6,'Prescribed pre-dose, continuous protection and final day 6 dose after ifosfamide ends.'),('hydration','Hydration and fluid monitoring',1,7,'Starts before ifosfamide and continues 24 hours after completion; the actual finish time controls timing.')],phases=[('continuous','Five-day high-dose ifosfamide and final protection',['Ifosfamide'],'high')],course='Maximum four 21-day cycles, stopping earlier for progression or unacceptable toxicity',urgent='Any change in alertness, confusion, hallucinations, seizures, blood in urine or reduced urine requires immediate assessment.',boundaries=['Prior or current grade 3 or worse neurotoxicity discontinues ifosfamide under this source; do not import the separate ifosfamide/etoposide re-exposure algorithm.','The final mesna oral alternative is mentioned without a complete conversion prescription; pharmacy must confirm it rather than assume intravenous and oral doses are interchangeable.','Kidney clearance below 50 mL/min and dialysis require a clinical decision. Severe liver impairment is not recommended.','Normal present counts do not erase prior neutropenic fever with a nadir below 0.5 ×10⁹/L, previous dose reductions, neurological stop history or other organ toxicity.'],tests=copy.deepcopy(common_ifos_tests))
 # Independent content review: preserve the precise postoperative context and
 # distinguish contraindicated coadministration from steroid avoidance.
 f['00100']['prep']='Confirm complete removal of all visible tumour, nonmetastatic eligibility and recovery from surgery. Calcineurin inhibitors such as ciclosporin and high-dose nonsteroidal anti-inflammatory painkillers must not be combined with mifamurtide. Check with oncology or the pharmacist before taking, starting, changing or stopping any medicine, including over-the-counter products; do not stop prescribed medicines yourself. Routine or chronic corticosteroids should be avoided, but emergency use is a separate medical decision. Any premedication requires an individual prescription, especially for a child. Arrange the separate 36-week treatment record.'
 f['00100']['wider']='After complete removal of all visible osteosarcoma in the stated nonmetastatic setting, the specialist sarcoma multidisciplinary team coordinates postoperative multi-agent chemotherapy, mifamurtide, rehabilitation and follow-up. Mifamurtide supplements chemotherapy; it does not replace it. Radiotherapy, if considered for an individual reason, is a separate multidisciplinary decision and does not substitute for this regimen’s required complete macroscopic resection and nonmetastatic context.'
 f['00100']['boundaries'][2]='Concurrent calcineurin inhibitors, including ciclosporin, and high-dose nonsteroidal anti-inflammatory drugs are contraindicated with mifamurtide. Routine or chronic corticosteroids should instead be avoided because they may oppose immune stimulation; emergency use is a separate clinical decision. Reconcile medicines with oncology/pharmacy rather than advising patient-led discontinuation.'
 f['00463']['boundaries'][1]='Distinct renal-source restrictions require specialist/pharmacy reconciliation: NCCP recommends creatinine clearance ≥50 mL/min before high-dose methotrexate, while its complication section prohibits treatment below an indexed 70 mL/min/1.73 m² and its renal-toxicity row contains a problematic ≥50 sign. Current HPRA high-dose methotrexate product information additionally contraindicates treatment at unindexed creatinine clearance below 60 mL/min (sections 4.2/4.3: https://assets.hpra.ie/products/Human/22092/Licence_PA0822-206-007_11092026121412.pdf). Do not equate or convert indexed and unindexed thresholds; these are not a patient dose or rescue calculator.'
 # Product-specific monitoring supplements are distinct from the national
 # minimum schedule. Retain both and require a written, reconciled plan.
 f['00463']['support']+=' Low blood counts or a delay to the next chemotherapy dose must not automatically withhold or stop folinic acid rescue for methotrexate already given.'
 for c in ['00420','00463']:
  heart=next(t for t in f[c]['tests']if t['label'].startswith('Heart'))
  heart['timing']+=' The linked doxorubicin product information additionally recommends baseline pumping-function imaging and repeats after approximately each accumulated 100 mg/m². The specialist team reconciles this with the national source and writes the cardiac monitoring schedule.'
  heart['source_ids']=['nccp','doxorubicin-pi']
  f[c]['boundaries'].append('Doxorubicin product information recommends baseline cardiac imaging and repeats at approximately each accumulated 100 mg/m², more explicit than the NCCP conditional-imaging paragraph. Use a reconciled specialist cardiac plan; the source age>65 phrase must not imply younger patients need no cardiac monitoring.')
 for c in ['00596','00680']:
  blood=next(t for t in f[c]['tests']if t['label']=='Full blood count')
  blood['timing']+=' Ifosfamide product information additionally specifies counts before each administration and appropriate intervals afterwards; the team reconciles the daily course monitoring.'
  blood['source_ids']=['nccp','ifosfamide-pi']
 for c,v in f.items():v['anatomy']=anatomy(c,' / '.join(x['name']for x in v['agents']))
 return f
